function _swapExactOutputMultihop(uint256 amount, address recipient, PathItem[] memory path, Options memory options) internal returns (uint256 amountIn) {
    address input = path[path.length - 1].token1;
    bytes memory encodedPath = _makeMultihopPath(path);
    bytes memory reversedPath = _reversePath(encodedPath); // reverses (token,fee) pair sequence
    ISwapRouter.ExactOutputParams memory params = ISwapRouter.ExactOutputParams({
        path: reversedPath,
        recipient: recipient,
        deadline: options.deadline,
        amountOut: amount,
        amountInMaximum: options.limitAmount
    });
    IERC20(input).safeTransferFrom(msg.sender, address(this), options.limitAmount);
    _approveERC20TokenIfNecessary(input, address(swapRouter));
    amountIn = swapRouter.exactOutput(params);
    require(amountIn <= options.limitAmount, "slippage exceeded");
    if (amountIn < options.limitAmount)
        IERC20(input).safeTransferFrom(address(this), recipient, options.limitAmount - amountIn);
}
